import {
  AutoAwesome,
  CheckCircle,
  CloudUpload,
  Code,
  Download,
  Error,
  Launch,
  Refresh,
  RocketLaunch,
  Speed,
  Timeline,
} from "@mui/icons-material";
import {
  Alert,
  Avatar,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Container,
  CssBaseline,
  Fade,
  Grid,
  LinearProgress,
  Paper,
  Slide,
  Stack,
  TextField,
  ThemeProvider,
  Typography,
  Zoom,
} from "@mui/material";
import React, { useEffect, useState } from "react";
import { getApiEndpoint, getWebSocketUrl } from "../config";
import { theme } from "../theme";
import {
  DeploymentResult,
  GenerateResponse,
  ProgressUpdate,
  UserRequest,
} from "../types";
import AnimatedBackground from "./AnimatedBackground";
import DemoPreview from "./DemoPreview";

const EnhancedApp: React.FC = () => {
  const [description, setDescription] = useState("");
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [progressUpdates, setProgressUpdates] = useState<ProgressUpdate[]>([]);
  const [result, setResult] = useState<DeploymentResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [validationError, setValidationError] = useState<string | null>(null);
  const [currentStep, setCurrentStep] = useState(0);
  const [showDemo, setShowDemo] = useState(false);

  // Check if description mentions coffee shop to show demo
  useEffect(() => {
    const coffeeKeywords = [
      "coffee",
      "café",
      "cafe",
      "espresso",
      "brew",
      "bean",
      "latte",
      "cappuccino",
    ];
    const hasCoffeeKeyword = coffeeKeywords.some((keyword) =>
      description.toLowerCase().includes(keyword),
    );
    setShowDemo(hasCoffeeKeyword && description.length > 10);
  }, [description]);

  const validateInput = (input: string): boolean => {
    if (!input || input.trim().length === 0) {
      setValidationError("Description cannot be empty");
      return false;
    }
    setValidationError(null);
    return true;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateInput(description)) {
      return;
    }

    setIsGenerating(true);
    setError(null);
    setProgressUpdates([]);
    setResult(null);
    setCurrentStep(0);

    try {
      const response = await fetch(getApiEndpoint("/api/generate"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          description: description.trim(),
        } as UserRequest),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "Failed to initiate generation");
      }

      const data: GenerateResponse = await response.json();
      setSessionId(data.session_id);
      connectWebSocket(data.session_id);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
      setIsGenerating(false);
    }
  };

  const connectWebSocket = (sessionId: string) => {
    const wsUrl = getWebSocketUrl(`/ws/${sessionId}`);
    const ws = new WebSocket(wsUrl);

    ws.onopen = () => {
      console.log("WebSocket connected");
    };

    ws.onmessage = (event) => {
      const update: ProgressUpdate = JSON.parse(event.data);
      console.log("WebSocket message received:", update);
      setProgressUpdates((prev) => [...prev, update]);
      setCurrentStep((prev) => prev + 1);

      if (update.type === "complete") {
        if (update.deployment_url) {
          setResult({
            success: true,
            url: update.deployment_url,
            execution_time: update.execution_time_ms || 0,
            project_summary: {
              page_count: 0,
              component_count: 0,
              file_count: 0,
            },
          });
          setIsGenerating(false);
        } else {
          setResult({
            success: true,
            execution_time: update.execution_time_ms || 0,
            project_summary: {
              page_count: 0,
              component_count: 0,
              file_count: 0,
            },
          });
          setIsGenerating(false);
        }
        fetchResult(sessionId);
      } else if (
        update.type === "error" &&
        update.message.includes("Workflow failed")
      ) {
        setError(update.message);
        setIsGenerating(false);
      }

      // Check for deployment completion in progress updates
      if (
        update.type === "progress" &&
        update.agent === "deployer" &&
        update.status === "completed" &&
        update.details &&
        update.details.includes("🌐 Deployment URL:")
      ) {
        const urlMatch = update.details.match(
          /🌐 Deployment URL:\s*(https?:\/\/[^\s\n]+)/,
        );
        if (urlMatch && urlMatch[1]) {
          setResult({
            success: true,
            url: urlMatch[1],
            execution_time: 0,
            project_summary: {
              page_count: 0,
              component_count: 0,
              file_count: 0,
            },
          });
          setIsGenerating(false);
          fetchResult(sessionId);
        }
      }
    };

    ws.onerror = (error) => {
      console.error("WebSocket error:", error);
      setError("Connection error occurred");
      setIsGenerating(false);
    };

    ws.onclose = () => {
      console.log("WebSocket disconnected");
    };
  };

  const fetchResult = async (sessionId: string) => {
    try {
      const response = await fetch(getApiEndpoint(`/api/result/${sessionId}`));
      if (!response.ok) {
        throw new Error("Failed to fetch result");
      }

      const data: DeploymentResult = await response.json();
      setResult((prev) => ({
        ...data,
        url: prev?.url || data.url,
      }));
      setIsGenerating(false);

      if (!data.success && data.error) {
        setError(data.error);
      }
    } catch (err) {
      if (!result?.url) {
        setError(err instanceof Error ? err.message : "Failed to fetch result");
        setIsGenerating(false);
      } else {
        setIsGenerating(false);
      }
    }
  };

  const handleReset = () => {
    setDescription("");
    setSessionId(null);
    setIsGenerating(false);
    setProgressUpdates([]);
    setResult(null);
    setError(null);
    setValidationError(null);
    setCurrentStep(0);
  };

  const getProgressIcon = (update: ProgressUpdate) => {
    if (update.status === "completed") return <CheckCircle color="success" />;
    if (update.status === "failed") return <Error color="error" />;
    return <CircularProgress size={20} />;
  };

  const getAgentAvatar = (agent: string) => {
    const avatarProps = {
      sx: { width: 32, height: 32, mr: 2 },
    };

    switch (agent) {
      case "planner":
        return (
          <Avatar
            {...avatarProps}
            sx={{ ...avatarProps.sx, bgcolor: "#667eea" }}
          >
            <Timeline />
          </Avatar>
        );
      case "coder":
        return (
          <Avatar
            {...avatarProps}
            sx={{ ...avatarProps.sx, bgcolor: "#f093fb" }}
          >
            <Code />
          </Avatar>
        );
      case "tester":
        return (
          <Avatar
            {...avatarProps}
            sx={{ ...avatarProps.sx, bgcolor: "#10b981" }}
          >
            <CheckCircle />
          </Avatar>
        );
      case "deployer":
        return (
          <Avatar
            {...avatarProps}
            sx={{ ...avatarProps.sx, bgcolor: "#f59e0b" }}
          >
            <CloudUpload />
          </Avatar>
        );
      default:
        return (
          <Avatar
            {...avatarProps}
            sx={{ ...avatarProps.sx, bgcolor: "#6b7280" }}
          >
            <AutoAwesome />
          </Avatar>
        );
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box
        sx={{
          minHeight: "100vh",
          position: "relative",
          overflow: "hidden",
          background:
            "linear-gradient(135deg, #0a0e27 0%, #1a1f3a 50%, #252b47 100%)",
        }}
      >
        <AnimatedBackground />

        <Container
          maxWidth="lg"
          sx={{ position: "relative", zIndex: 1, py: 4 }}
        >
          {/* Header Section */}
          <Fade in timeout={800}>
            <Box textAlign="center" mb={6}>
              <Typography
                variant="h1"
                component="h1"
                sx={{
                  mb: 2,
                  background:
                    "linear-gradient(135deg, #667eea, #764ba2, #f093fb)",
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                  backgroundClip: "text",
                  animation: "gradient-shift 4s ease infinite",
                  "@keyframes gradient-shift": {
                    "0%": { backgroundPosition: "0% 50%" },
                    "50%": { backgroundPosition: "100% 50%" },
                    "100%": { backgroundPosition: "0% 50%" },
                  },
                }}
              >
                AMAR
              </Typography>

              <Stack
                direction="row"
                alignItems="center"
                justifyContent="center"
                spacing={2}
                mb={2}
              >
                <Box
                  sx={{
                    width: 60,
                    height: 2,
                    background:
                      "linear-gradient(90deg, transparent, #667eea, transparent)",
                  }}
                />
                <Typography
                  variant="h6"
                  sx={{
                    color: "text.secondary",
                    letterSpacing: "0.2em",
                    textTransform: "uppercase",
                  }}
                >
                  Autonomous Multi-Agent React
                </Typography>
                <Box
                  sx={{
                    width: 60,
                    height: 2,
                    background:
                      "linear-gradient(90deg, transparent, #667eea, transparent)",
                  }}
                />
              </Stack>

              <Typography
                variant="body1"
                color="text.secondary"
                sx={{ maxWidth: 600, mx: "auto" }}
              >
                Transform ideas into deployed applications with AI-powered
                agents
              </Typography>
            </Box>
          </Fade>

          {/* Main Content */}
          <Grid container spacing={4} justifyContent="center">
            <Grid item xs={12} md={8}>
              {/* Input Form */}
              {!isGenerating && !result && (
                <Slide direction="up" in timeout={600}>
                  <Card elevation={0}>
                    <CardContent sx={{ p: 4 }}>
                      <Stack
                        direction="row"
                        alignItems="center"
                        spacing={2}
                        mb={3}
                      >
                        <AutoAwesome
                          sx={{ color: "primary.main", fontSize: 32 }}
                        />
                        <Typography variant="h2" component="h2">
                          Describe Your Application
                        </Typography>
                      </Stack>

                      <Typography variant="body1" color="text.secondary" mb={4}>
                        Tell us what kind of web application you'd like to
                        build. We'll plan, code, test, and deploy it for you
                        automatically.
                      </Typography>

                      <Box component="form" onSubmit={handleSubmit}>
                        <TextField
                          fullWidth
                          multiline
                          rows={6}
                          placeholder="Example: Build a landing page for a coffee shop with a menu, about section, and contact form..."
                          value={description}
                          onChange={(e) => {
                            setDescription(e.target.value);
                            if (validationError) {
                              validateInput(e.target.value);
                            }
                          }}
                          onBlur={() => validateInput(description)}
                          error={!!validationError}
                          helperText={validationError}
                          sx={{ mb: 3 }}
                        />

                        <Button
                          type="submit"
                          variant="contained"
                          size="large"
                          fullWidth
                          disabled={isGenerating || !description.trim()}
                          startIcon={<RocketLaunch />}
                          sx={{ py: 2, fontSize: "1.2rem" }}
                        >
                          Generate Application
                        </Button>
                      </Box>

                      {/* Demo Preview */}
                      {showDemo && (
                        <Fade in timeout={800}>
                          <Box mt={3}>
                            <Typography
                              variant="h6"
                              mb={2}
                              textAlign="center"
                              color="text.secondary"
                            >
                              Preview: Here's what your coffee shop landing page
                              might look like
                            </Typography>
                            <DemoPreview />
                          </Box>
                        </Fade>
                      )}

                      <Alert severity="info" sx={{ mt: 3 }}>
                        <strong>💡 Note:</strong> Maximum 5 pages per
                        application. Generation typically takes 3-5 minutes.
                      </Alert>

                      {error && (
                        <Alert severity="error" sx={{ mt: 2 }}>
                          <strong>⚠️ Error:</strong> {error}
                        </Alert>
                      )}
                    </CardContent>
                  </Card>
                </Slide>
              )}

              {/* Progress Display */}
              {isGenerating && (
                <Slide direction="up" in timeout={600}>
                  <Card elevation={0}>
                    <CardContent sx={{ p: 4 }}>
                      <Stack
                        direction="row"
                        alignItems="center"
                        spacing={2}
                        mb={3}
                      >
                        <Speed sx={{ color: "primary.main", fontSize: 32 }} />
                        <Typography variant="h2" component="h2">
                          Generating Your Application
                        </Typography>
                      </Stack>

                      <Typography variant="body1" color="text.secondary" mb={4}>
                        Please wait while our agents plan, build, test, and
                        deploy your application...
                      </Typography>

                      <LinearProgress
                        variant="indeterminate"
                        sx={{ mb: 4, height: 8, borderRadius: 4 }}
                      />

                      <Stack spacing={2}>
                        {progressUpdates.map((update, index) => (
                          <Zoom
                            in
                            key={index}
                            timeout={300}
                            style={{ transitionDelay: `${index * 100}ms` }}
                          >
                            <Paper
                              elevation={0}
                              sx={{
                                p: 3,
                                background:
                                  update.status === "completed"
                                    ? "rgba(16, 185, 129, 0.1)"
                                    : update.status === "failed"
                                      ? "rgba(239, 68, 68, 0.1)"
                                      : "rgba(59, 130, 246, 0.1)",
                                border: "1px solid",
                                borderColor:
                                  update.status === "completed"
                                    ? "rgba(16, 185, 129, 0.3)"
                                    : update.status === "failed"
                                      ? "rgba(239, 68, 68, 0.3)"
                                      : "rgba(59, 130, 246, 0.3)",
                                borderRadius: 2,
                                transition: "all 0.3s ease",
                                "&:hover": {
                                  transform: "translateX(8px)",
                                },
                              }}
                            >
                              <Stack
                                direction="row"
                                alignItems="flex-start"
                                spacing={2}
                              >
                                {update.agent && getAgentAvatar(update.agent)}
                                <Box sx={{ flex: 1 }}>
                                  <Stack
                                    direction="row"
                                    alignItems="center"
                                    spacing={2}
                                    mb={1}
                                  >
                                    {getProgressIcon(update)}
                                    <Typography
                                      variant="body1"
                                      fontWeight={600}
                                    >
                                      {update.agent && (
                                        <Chip
                                          label={`${update.agent} Agent`}
                                          size="small"
                                          sx={{
                                            mr: 1,
                                            textTransform: "capitalize",
                                          }}
                                        />
                                      )}
                                      {update.message}
                                    </Typography>
                                  </Stack>
                                  {update.details && (
                                    <Typography
                                      variant="body2"
                                      color="text.secondary"
                                      sx={{ ml: 4 }}
                                    >
                                      {update.details}
                                    </Typography>
                                  )}
                                </Box>
                              </Stack>
                            </Paper>
                          </Zoom>
                        ))}
                      </Stack>

                      {error && (
                        <Alert severity="error" sx={{ mt: 3 }}>
                          <strong>⚠️ Error:</strong> {error}
                          <Button onClick={handleReset} sx={{ ml: 2 }}>
                            Try Again
                          </Button>
                        </Alert>
                      )}
                    </CardContent>
                  </Card>
                </Slide>
              )}

              {/* Result Display */}
              {result && !isGenerating && (
                <Zoom in timeout={800}>
                  <Card elevation={0}>
                    <CardContent sx={{ p: 4 }}>
                      <Stack
                        direction="row"
                        alignItems="center"
                        spacing={2}
                        mb={3}
                      >
                        {result.success ? (
                          <CheckCircle
                            sx={{ color: "success.main", fontSize: 40 }}
                          />
                        ) : (
                          <Error sx={{ color: "error.main", fontSize: 40 }} />
                        )}
                        <Typography variant="h2" component="h2">
                          {result.success
                            ? "Application Deployed!"
                            : "Deployment Failed"}
                        </Typography>
                      </Stack>

                      {result.success && (
                        <Box mb={4}>
                          {result.url ? (
                            <>
                              <Typography
                                variant="body1"
                                color="text.secondary"
                                mb={3}
                              >
                                Your application has been successfully deployed
                                and is now live!
                              </Typography>

                              <Button
                                variant="contained"
                                size="large"
                                fullWidth
                                href={result.url}
                                target="_blank"
                                rel="noopener noreferrer"
                                startIcon={<Launch />}
                                sx={{ mb: 2, py: 2, fontSize: "1.2rem" }}
                              >
                                View Your Application
                              </Button>

                              <Paper
                                elevation={0}
                                sx={{
                                  p: 2,
                                  background: "rgba(255, 255, 255, 0.05)",
                                  border: "1px solid rgba(255, 255, 255, 0.1)",
                                  borderRadius: 2,
                                  display: "flex",
                                  alignItems: "center",
                                  gap: 2,
                                }}
                              >
                                <Launch />
                                <Typography
                                  variant="body2"
                                  sx={{
                                    fontFamily: "monospace",
                                    wordBreak: "break-all",
                                  }}
                                >
                                  {result.url}
                                </Typography>
                              </Paper>
                            </>
                          ) : (
                            <Alert severity="warning">
                              <strong>⚠️ Deployment Status:</strong> Application
                              has been generated and tested successfully, but
                              deployment URL is not available. You can download
                              the project files below to deploy manually.
                            </Alert>
                          )}
                        </Box>
                      )}

                      {/* Project Summary */}
                      {result.project_summary && (
                        <Box mb={4}>
                          <Typography variant="h6" mb={2}>
                            Project Summary
                          </Typography>
                          <Grid container spacing={2}>
                            <Grid item xs={6} sm={3}>
                              <Paper
                                elevation={0}
                                sx={{
                                  p: 2,
                                  textAlign: "center",
                                  background: "rgba(255, 255, 255, 0.05)",
                                }}
                              >
                                <Typography
                                  variant="h4"
                                  color="primary.main"
                                  fontWeight={700}
                                >
                                  {result.project_summary.page_count}
                                </Typography>
                                <Typography
                                  variant="caption"
                                  color="text.secondary"
                                  textTransform="uppercase"
                                >
                                  Pages
                                </Typography>
                              </Paper>
                            </Grid>
                            <Grid item xs={6} sm={3}>
                              <Paper
                                elevation={0}
                                sx={{
                                  p: 2,
                                  textAlign: "center",
                                  background: "rgba(255, 255, 255, 0.05)",
                                }}
                              >
                                <Typography
                                  variant="h4"
                                  color="secondary.main"
                                  fontWeight={700}
                                >
                                  {result.project_summary.component_count}
                                </Typography>
                                <Typography
                                  variant="caption"
                                  color="text.secondary"
                                  textTransform="uppercase"
                                >
                                  Components
                                </Typography>
                              </Paper>
                            </Grid>
                            <Grid item xs={6} sm={3}>
                              <Paper
                                elevation={0}
                                sx={{
                                  p: 2,
                                  textAlign: "center",
                                  background: "rgba(255, 255, 255, 0.05)",
                                }}
                              >
                                <Typography
                                  variant="h4"
                                  color="success.main"
                                  fontWeight={700}
                                >
                                  {result.project_summary.file_count}
                                </Typography>
                                <Typography
                                  variant="caption"
                                  color="text.secondary"
                                  textTransform="uppercase"
                                >
                                  Files
                                </Typography>
                              </Paper>
                            </Grid>
                            <Grid item xs={6} sm={3}>
                              <Paper
                                elevation={0}
                                sx={{
                                  p: 2,
                                  textAlign: "center",
                                  background: "rgba(255, 255, 255, 0.05)",
                                }}
                              >
                                <Typography
                                  variant="h4"
                                  color="warning.main"
                                  fontWeight={700}
                                >
                                  {result.execution_time
                                    ? `${(result.execution_time / 1000).toFixed(1)}s`
                                    : "N/A"}
                                </Typography>
                                <Typography
                                  variant="caption"
                                  color="text.secondary"
                                  textTransform="uppercase"
                                >
                                  Time
                                </Typography>
                              </Paper>
                            </Grid>
                          </Grid>
                        </Box>
                      )}

                      {/* Download Button */}
                      {sessionId && (
                        <Box mb={3}>
                          <Button
                            variant="outlined"
                            size="large"
                            fullWidth
                            startIcon={<Download />}
                            onClick={() => {
                              const downloadUrl = getApiEndpoint(
                                `/api/download/${sessionId}`,
                              );
                              window.location.href = downloadUrl;
                            }}
                            sx={{ py: 2 }}
                          >
                            Download Project Files
                          </Button>
                          <Typography
                            variant="body2"
                            color="text.secondary"
                            textAlign="center"
                            mt={1}
                          >
                            Download the complete project as a ZIP file to
                            customize or deploy manually
                          </Typography>
                        </Box>
                      )}

                      {!result.success && result.error && (
                        <Alert severity="error" sx={{ mb: 3 }}>
                          <strong>❌ Error:</strong> {result.error}
                        </Alert>
                      )}

                      <Button
                        variant="outlined"
                        size="large"
                        fullWidth
                        startIcon={<Refresh />}
                        onClick={handleReset}
                        sx={{ py: 2 }}
                      >
                        Generate Another Application
                      </Button>
                    </CardContent>
                  </Card>
                </Zoom>
              )}
            </Grid>
          </Grid>
        </Container>
      </Box>
    </ThemeProvider>
  );
};

export default EnhancedApp;
